 const items=state.cart.map((p,index)=>`<article class="receipt-item"><div class="receipt-product"><strong>${esc(productTitle(p.title)||'Untitled product')}</strong><span>${esc(p.merchant||'Unknown retailer')}</span><div class="receipt-actions"><a class="inline-action" target="_blank" rel="noopener noreferrer" href="${esc(listingLink(p))}">Search ${esc(p.merchant||'retailer')} ↗</a><button class="inline-action" data-action="cart-remove-index" data-index="${index}">Remove</button></div></div><strong class="receipt-price">${money(p.price)}</strong></article>`).join('');
