function renderCartReceipt(){const root=$('cart-modal-root');if(!root)return;if(!state.cartReceiptOpen){root.innerHTML='';return}const sum=state.cart.reduce((total,item)=>total+(Number.isFinite(item.price)?item.price:0),0);root.innerHTML=`<div class="cart-receipt-overlay" data-action="cart-receipt-backdrop"><section class="cart-receipt" role="dialog" aria-modal="true" aria-labelledby="cart-receipt-title"><header class="cart-receipt-head"><div><span class="receipt-kicker">BUDGETBUDDY · SHORTLIST</span><h2 id="cart-receipt-title">Shopping list</h2></div><button class="cart-receipt-close" type="button" data-action="cart-receipt-close" aria-label="Close shopping list" autofocus>${fa('xmark')}</button></header><div class="cart-receipt-meta"><span>ITEM</span><span>PRICE</span></div>${state.cart.length?`<div class="cart-receipt-items">${state.cart.map((item,index)=>`<article class="cart-receipt-item"><div class="cart-receipt-product"><strong>${esc(productTitle(item.title)||'Untitled product')}</strong><span>${esc(item.merchant||'Unknown retailer')}</span><div class="receipt-actions"><a class="inline-action" target="_blank" rel="noopener noreferrer" href="${esc(listingLink(item))}">Search ${esc(item.merchant||'retailer')} ↗</a><button class="inline-action" type="button" data-action="cart-remove-index" data-index="${index}">Remove</button></div></div><strong class="cart-receipt-price">${money(item.price)}</strong></article>`).join('')}</div><div class="cart-receipt-total"><span>TOTAL · LISTED ITEM PRICES</span><strong>${money(sum)}</strong></div>`:'<p class="cart-receipt-empty">Your shopping list is empty.</p>'}</section></div>`}
function renderPromoAnswer(text,allowSave=false){
 const normalized=String(text).replace(/\s+-\s+(?=(?:\*\*)?[A-Za-z][A-Za-z0-9 &.'’()-]{1,40}\s+[—–]\s*)/g,'\n- ');
 const output=[];let paragraph=[],items=[],itemIndex=0;
 const flushParagraph=()=>{if(paragraph.length){output.push(`<p>${paragraph.map(renderAiLine).join(' ')}</p>`);paragraph=[]}};
 const flushItems=()=>{if(items.length){output.push(`<ul class="promo-result-list">${items.map(item=>{const index=itemIndex++,code=promoCodeFromItem(item),saved=code&&isPromoCodeSaved(code);const saveButton=allowSave&&code?` <button type="button" class="sm-btn promo-code-save" data-action="promo-save-code" data-index="${index}"${saved?' disabled':''}>${saved?'Saved':'Save code'}</button>`:'';return `<li>${renderPromoInline(item)}${saveButton}</li>`}).join('')}</ul>`);items=[]}};
 for(const line of normalized.split(/\r?\n/)){
  if(/^\s{0,3}#{1,6}\s+/.test(line)){flushParagraph();flushItems();output.push(`<p>${renderAiLine(line)}</p>`);continue}
  const bullet=line.match(/^\s*[-*]\s+(.+)$/);
  if(bullet){flushParagraph();items.push(bullet[1].trim());continue}
  flushItems();
  if(line.trim())paragraph.push(line.trim());else flushParagraph();
 }
 flushParagraph();flushItems();
 return output.join('');
}
function promoAnswerItems(text){const normalized=String(text).replace(/\s+-\s+(?=(?:\*\*)?[A-Za-z][A-Za-z0-9 &.'’()-]{1,40}\s+[—–]\s*)/g,'\n- ');return normalized.split(/\r?\n/).flatMap(line=>{const bullet=line.match(/^\s*[-*]\s+(.+)$/);return bullet?[bullet[1].trim()]:[]})}
function promoCodeFromItem(item){const text=String(item),match=text.match(/`([^`]+)`/)||text.match(/\*\*([A-Za-z0-9][A-Za-z0-9_-]{1,39})\*\*/) ||text.match(/\[([A-Za-z0-9][A-Za-z0-9_-]{1,39})\]\(https:\/\/[^\s)]+\)/);if(!match)return '';const code=match[1].trim();return /^[A-Za-z0-9][A-Za-z0-9_-]{1,39}$/.test(code)?code:''}
function promoCodesFromAnswer(answer){return [...new Set(promoAnswerItems(answer).map(promoCodeFromItem).filter(Boolean).map(code=>code.toUpperCase()))]}
function removeDuplicateSavedPromos(promos){const seen=new Set();return promos.filter(promo=>{const codes=promoCodesFromAnswer(promo.answer);if(codes.length===1&&seen.has(codes[0]))return false;codes.forEach(code=>seen.add(code));return true})}
function isPromoCodeSaved(code){const normalized=String(code||'').trim().toUpperCase();return !!normalized&&state.savedPromos.some(promo=>promoCodesFromAnswer(promo.answer).includes(normalized))}
const uniqueSavedPromos=removeDuplicateSavedPromos(state.savedPromos);if(uniqueSavedPromos.length!==state.savedPromos.length){state.savedPromos=uniqueSavedPromos;save()}
function renderPromoInline(text){
 const pattern=/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]\n]+\]\(https:\/\/[^\s)]+\))/g;
 return String(text).split(pattern).map(part=>{
  if(/^`[^`]+`$/.test(part))return `<code class="promo-code-token">${esc(part.slice(1,-1))}</code>`;
  if(/^\*\*[^*]+\*\*$/.test(part)){const value=part.slice(2,-2);return /^[A-Za-z0-9][A-Za-z0-9_-]{1,39}$/.test(value)?`<code class="promo-code-token">${esc(value)}</code>`:`<strong>${renderPromoInline(value)}</strong>`}
  return renderChatInline(part);
 }).join('');
}
function renderSavedPromo(promo){return `<article class="saved-promo"><div class="saved-promo-heading"><div><h4>${esc(promo.query)}</h4><span>${esc(promo.savedAt?new Date(promo.savedAt).toLocaleString():'Saved promo codes')}</span></div><button type="button" class="inline-action" data-action="promo-remove" data-id="${esc(promo.id)}">Remove</button></div><div class="promo-answer-body">${renderPromoAnswer(promo.answer)}</div></article>`}
