 $('right').innerHTML=`<section class="surface assistant-panel conversation-panel ${state.enteringConversation?'conversation-enter':''}"><div class="chat-head"><span class="chat-mascot float" aria-hidden="true">${ART.mini}</span><div class="chat-head-copy"><h3 class="chat-title">BudgetBuddy assistant</h3><div class="chat-status"><span class="${enabled?'live-pill':'status-pill'}"><span class="online" aria-hidden="true"></span>${enabled?'AI configured':'AI needed for live search'}</span><span class="chat-sub">${enabled?`Answers via ${esc(state.aiProvider)}`:'Live web search and AI answers'}</span></div></div><span class="chat-head-spark chat-head-spark-a twinkle" aria-hidden="true">${fa('star')}</span><span class="chat-head-spark chat-head-spark-b twinkle d2" aria-hidden="true">${fa('star')}</span></div><div class="chat-box" id="chat-scroll" aria-live="polite">${chats}${state.pending?pendingBubble('Searching published listings…'):''}${state.chatPending?pendingBubble(esc(state.chatPendingText||'Thinking…')):''}<div class="quick-actions"><button type="button" data-action="help">${fa('wand-magic-sparkles')}What can you do?</button></div></div><div class="chat-foot"><form class="chat-input" id="chat-form"><label class="sr-only" for="chat-text">Ask BudgetBuddy</label><input type="text" id="chat-text" maxlength="2000" placeholder="Ask me anything..."/><button class="chat-send" type="submit" aria-label="Send message" ${state.chatPending?'disabled':''}>${fa('paper-plane')}</button></form><div class="chat-privacy">${enabled?'BudgetBuddy assistant can make mistakes. Please double-check important info.':'Configure AI_BASE_URL, AI_API_KEY, and AI_MODEL on the server to enable web search and AI answers.'} Never share passwords or payment details.</div></div></section>${shoppingList}`;
