function render(){navigation();header();renderExtensionSetup();const assistant=state.page==='assistant';document.body.classList.toggle('assistant-page',assistant);document.body.classList.toggle('saved-notes-page',state.page==='saved');document.body.classList.toggle('shopping-list-page',state.page==='cart');document.body.classList.toggle('promo-codes-page',state.page==='promos');$('workspace').classList.toggle('assistant-layout',assistant);$('workspace').classList.toggle('general-layout',!assistant);$('promos').innerHTML='';if(assistant){$('center').innerHTML=''}else if(state.page==='saved')renderSaved();else if(state.page==='cart')renderCart();else renderPromoCodes();renderRight(false);renderCartReceipt()}
function takeSnapshot(p){return {title:p.title,merchant:p.merchant,price:p.price,url:p.url,seen:p.observedAt}}
function addSnapshot(field,p){const index=state[field].findIndex(x=>p.url?x.url===p.url:normalizeProduct(x.title)===normalizeProduct(p.title)&&normalizeProduct(x.merchant)===normalizeProduct(p.merchant));if(index!==-1){state[field].splice(index,1);toast('Removed from '+(field==='cart'?'shopping list':'saved notes'));}else{state[field].push(takeSnapshot(p));toast(field==='cart'?'Added to shopping list':'Saved to notes')}save();render()}
async function checkStatus(){try{const r=await apiFetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error('Could not load BudgetBuddy server status.');const status=await r.json();state.extensionSetupError='';state.requiresSearchCode=!!status.shoppingRequiresCode;state.aiConfigured=!!status.aiConfigured;state.aiProvider=String(status.aiProvider||'');state.requiresChatCode=!!status.requiresCode;}catch(error){state.aiConfigured=false;state.aiProvider='';state.extensionSetupError=isExtensionRuntime()?error.message||'Unable to connect to the BudgetBuddy server.':''}render()}
function accessCode(type){const isSearch=type==='search';const prop=isSearch?'searchCode':'chatCode';const needed=isSearch?state.requiresSearchCode:state.requiresChatCode;if(!needed||state[prop])return true;const code=window.prompt(`Enter the private BudgetBuddy ${isSearch?'search':'AI'} access code (not a shopping password):`);if(!code?.trim())return false;state[prop]=code.trim();sessionStorage.setItem(isSearch?'sw-search-code':'sw-chat-code',state[prop]);return true}
async function search(q){q=String(q||'').trim();if(!q)return;if(!accessCode('search'))return;state.query=q;state.pending=true;state.error='';state.results=[];state.fetchedAt='';state.page='assistant';render();
 try{const res=await apiFetch('/api/search?q='+encodeURIComponent(q),{headers:state.searchCode?{'X-Shopwise-Search-Code':state.searchCode}:{},signal:AbortSignal.timeout(70000)});const data=await res.json();if(!res.ok){if(res.status===401){state.searchCode='';sessionStorage.removeItem('sw-search-code')}throw new Error(data.error||'Search failed')}state.results=Array.isArray(data.products)?data.products:[];state.fetchedAt=data.fetchedAt||'';if(state.personalize){state.history=[q,...state.history.filter(x=>x!==q)].slice(0,15);save()}addChat('assistant',state.results.length?summaryText():`No sourced listings were found for "${q}". Try another search or ask me about the product.`)}catch(e){state.error=e.name==='TimeoutError'?'Search timed out. Try again.':e.message||'Search unavailable.';addChat('assistant',`Search failed: ${state.error}`,true)}finally{state.pending=false;render()}}
function savePromoCode(index){if(!state.promoAnswer)return;const item=promoAnswerItems(state.promoAnswer)[index],code=promoCodeFromItem(item);if(!item||!code)return;if(isPromoCodeSaved(code)){toast('Promo code already saved');return}const promo={id:`promo-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,query:state.promoQuery,answer:`- ${item}`,savedAt:new Date().toISOString()};state.savedPromos.push(promo);state.savedPromos=state.savedPromos.slice(-100);save();toast('Promo code saved');render()}
async function findPromoCodes(query){query=String(query||'').trim();if(!query||state.promoPending)return;if(!accessCode('chat'))return;state.promoQuery=query;state.promoPending=true;state.promoError='';state.promoAnswer='';render();try{const response=await apiFetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...(state.chatCode?{'X-Shopwise-Code':state.chatCode}:{})},body:JSON.stringify({message:`Find current promo codes for ${query}. Search online now and report only exact codes supported by cited sources.`,context:{promoCodeSearch:true}}),signal:AbortSignal.timeout(130000)});const data=await response.json();if(!response.ok){if(response.status===401){state.chatCode='';sessionStorage.removeItem('sw-chat-code')}throw new Error(data.error||'Promo-code search failed')}state.promoAnswer=data.reply||'The AI returned no answer.'}catch(error){state.promoError=error.name==='TimeoutError'?'Promo-code search timed out. Please try again.':error.message||'Promo-code search failed.'}finally{state.promoPending=false;render()}}
function addChat(role,text,error=false){if(role==='assistant'&&!String(text).startsWith('Hello!'))text=`Hello! ${text}`;state.chats.push({role,text,error});state.chats=state.chats.slice(-45);renderRight()}
function addFirstUserMessage(text){const shouldTransition=state.page==='assistant'&&!state.chats.length;if(!shouldTransition){addChat('user',text);return}if(typeof document.startViewTransition==='function'){document.startViewTransition(()=>addChat('user',text));return}state.enteringConversation=true;addChat('user',text)}
function renderChatInline(text){const pattern=/(!\[([^\]\n]*)\]\((https:\/\/[^\s)]+)\)|\[([^\]\n]+)\]\((https:\/\/[^\s)]+)\)|\*\*([^*]+)\*\*)/g;let html='',last=0,match;while((match=pattern.exec(String(text)))){html+=esc(text.slice(last,match.index));if(match[2]){try{const url=new URL(match[3]);if(url.protocol==='https:'&&!url.username&&!url.password)html+=`<img class="chat-product-image" src="${esc(url.href)}" alt="${esc(match[2])}" loading="lazy" referrerpolicy="no-referrer">`;else html+=esc(match[0])}catch{html+=esc(match[0])}}else if(match[4]){try{const url=new URL(match[5]);if(url.protocol==='https:'&&!url.username&&!url.password)html+=`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(match[4])}</a>`;else html+=esc(match[0])}catch{html+=esc(match[0])}}else html+=`<strong>${esc(match[6])}</strong>`;last=pattern.lastIndex}return html+esc(String(text).slice(last))}
function renderAiLine(line){const heading=String(line).match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/);return heading?`<strong class="ai-response-heading">${renderChatInline(heading[1])}</strong>`:renderChatInline(line)}
function tableCellText(cell){return String(cell).replace(/\[([^\]]+)\]\([^)]+\)/i,'$1').replace(/\*\*/g,'').replace(/`/g,'').trim()}
function safeTableUrl(value){try{const url=new URL(value);if(url.protocol==='https:'&&!url.username&&!url.password)return url.href}catch{}return ''}
function renderChatProductCell(cell,product){
 const link=String(cell).match(/^\[([^\]\n]+)\]\(([^)\s]+)\)$/);
 if(!link)return renderChatInline(cell);
 const url=safeTableUrl(link[2])||safeTableUrl(product.url)||`https://www.google.com/search?q=${encodeURIComponent(`${product.title} ${product.merchant}`)}`;
 return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(link[1])}</a>`:esc(link[1]);
}
function renderChatTableCell(cell){return String(cell).split(/<br\s*\/?>/i).map(renderChatInline).join('<br>')}
function chatTableProduct(cells,headers){
 const normalize=value=>String(value).normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]+/gu,'');
 const productColumn=headers.findIndex(value=>/\bproduct\b|\bitem\b/i.test(value));
 const retailerColumn=headers.findIndex(value=>/\bretailer\b|\bmerchant\b|\bstore\b/i.test(value));
 const priceColumn=headers.findIndex(value=>/\bprice\b/i.test(value));
 const title=tableCellText(cells[productColumn>=0?productColumn:0]||'');
 const merchant=tableCellText(cells[retailerColumn]||'')||'Unknown retailer';
 const priceText=tableCellText(cells[priceColumn]||'');
 const amount=priceText.match(/(?:S\$|SGD\s*|\$)?\s*([\d,]+(?:\.\d{1,2})?)/i);
 const price=amount?Number(amount[1].replaceAll(',','')):null;
 const link=cells.map(cell=>cell.match(/\[([^\]\n]+)\]\(([^)\s]+)\)/i)).find(Boolean);
 const linkedUrl=link&&safeTableUrl(link[2]);
 const linkedProduct=linkedUrl&&state.results.find(item=>item.url===linkedUrl||listingLink(item)===linkedUrl);
 if(linkedProduct)return linkedProduct;
 const candidates=state.results.filter(item=>normalize(item.title)===normalize(title));
 if(candidates.length===1)return candidates[0];
 if(candidates.length>1){
  const retailerMatches=candidates.filter(item=>[item.merchant,item.source].some(name=>{
   const retailer=normalize(name).replace(/1$/,'');
   return retailer&&normalize(merchant).includes(retailer);
  }));
  if(retailerMatches.length===1)return retailerMatches[0];
  if(price!==null){
   const priceMatches=candidates.filter(item=>item.price===price);
   if(priceMatches.length===1)return priceMatches[0];
  }
 }
 if(!title)return null;
 const product={id:`chat-${state.chatProducts.length}`,title,merchant,price:Number.isFinite(price)&&price>=0?price:null,url:linkedUrl||'',observedAt:new Date().toISOString()};
 product.url=product.url||listingLink(product);
 return product;
}
function cartContains(product){return state.cart.some(item=>product.url?item.url===product.url:normalizeProduct(item.title)===normalizeProduct(product.title)&&normalizeProduct(item.merchant)===normalizeProduct(product.merchant))}
function normalizeProduct(value){return String(value||'').normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]+/gu,'')}
function renderChatText(text,interactive=true,savedNoteId=''){const lines=String(text).split('\n');let html='',index=0;while(index<lines.length){if(lines[index].trim().startsWith('|')&&index+1<lines.length&&/^\s*\|?(?:\s*:?-{3,}:?\s*\|)+\s*:?-{3,}:?\s*\|?\s*$/.test(lines[index+1])){const parseRow=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(cell=>cell.trim());const headers=parseRow(lines[index]);const productColumn=headers.findIndex(cell=>/\bproduct\b|\bitem\b/i.test(cell));const listColumn=headers.findIndex(cell=>/shopping list/i.test(cell));index+=2;let rows='';while(index<lines.length&&lines[index].trim().startsWith('|')){const cells=parseRow(lines[index]);const product=interactive?chatTableProduct(cells,headers):null;let button='';if(product){const products=savedNoteId?(state.noteProducts[savedNoteId]||(state.noteProducts[savedNoteId]=[])):state.chatProducts;const productIndex=products.push(product)-1;const added=cartContains(product);button=`<button class="chat-list-button" data-action="${savedNoteId?'saved-note-cart-add':'chat-cart-add'}" ${savedNoteId?`data-note-id="${esc(savedNoteId)}"`:''} data-index="${productIndex}" ${added?'disabled':''}>${added?'&#10003; Added':'+ Add to shopping list'}</button>`}rows+=`<tr>${cells.map((cell,cellIndex)=>interactive&&cellIndex===listColumn?`<td>${button||'<button class="chat-list-button" disabled>Unavailable</button>'}</td>`:interactive&&cellIndex===productColumn&&product?`<td>${renderChatProductCell(cell,product)}</td>`:`<td>${renderChatTableCell(cell)}</td>`).join('')}</tr>`;index++}html+=`<div class="chat-table-scroll"><table class="chat-table"><thead><tr>${headers.map(cell=>`<th scope="col">${esc(cell)}</th>`).join('')}</thead><tbody>${rows}</tbody></table></div>`;continue}html+=renderAiLine(lines[index])+(index<lines.length-1?'\n':'');index++}return html}
function cheapestText(){if(!state.results.length)return 'Search for a product first. BudgetBuddy will show sourced shopping results with prices and retailer links.';const r=state.results[0],url=listingLink(r),title=url?`[${r.title.replace(/[|\[\]\r\n]/g,' ')}](${url.replace(/[)|]/g,char=>encodeURIComponent(char))})`:r.title.replace(/[|\[\]\r\n]/g,' ');return `Hello! Here is the lowest listed result:\n\n| Product | Retailer | Listed price (SGD) | Relevant details | Shopping list |\n| --- | --- | ---: | --- | --- |\n| ${title} | ${String(r.merchant).replace(/[|\r\n]/g,' ')} | ${money(r.price)} | ${String(r.delivery||'—').replace(/[|\r\n]/g,' ')} | + Add to shopping list |\n\nPrices can vary by exact product and checkout. Verify details with the retailer.`}
function summaryText(){if(!state.results.length)return 'No results to compare yet. Search for an exact product name and size first.';const top=state.results.slice().sort((a,b)=>a.price-b.price).slice(0,12);const clean=value=>String(value||'').replace(/[|\[\]\r\n]/g,' ').replace(/\s+/g,' ').trim();const link=(label,raw)=>{try{const url=new URL(raw);if(url.protocol!=='https:'||url.username||url.password)return clean(label);return `[${clean(label)}](${url.href.replace(/[)|]/g,char=>encodeURIComponent(char))})`}catch{return clean(label)}};return 'Hello! Here are the lowest published item prices in your results:\n\n| Product | Retailer | Listed price (SGD) | Relevant details | Shopping list |\n| --- | --- | ---: | --- | --- |\n'+top.map(x=>{const destination=listingLink(x);return `| ${link(x.title,destination)} | ${clean(x.merchant)} | ${money(x.price)} | ${clean(x.promotion||x.delivery)||'—'} | + Add to shopping list |`}).join('\n')+'\n\nPrices and promotions are shown as reported in retrieved listings. Offers may have conditions or expiry dates; product sizes may differ. Check the retailer listing for availability, delivery, and final checkout price.'}
async function requestAIReply(msg,history,context){const timeout=['grocery-finding','recipe-ingredients'].includes(context.savedNoteCategory)?270000:130000;const resp=await apiFetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...(state.chatCode?{'X-Shopwise-Code':state.chatCode}:{})},body:JSON.stringify({message:msg,history,context}),signal:AbortSignal.timeout(timeout)});const data=await resp.json();if(!resp.ok){if(resp.status===401){state.chatCode='';sessionStorage.removeItem('sw-chat-code')}throw new Error(data.error||'AI unavailable')}return data.reply||'The AI returned no answer.'}
async function chat(msg,{savedNoteId,savedNoteCategory='general',showUserMessage=true}={}){
 msg=String(msg||'').trim();const noteRequest=typeof savedNoteId==='string';if(!msg||(!noteRequest&&state.chatPending))return;if(noteRequest&&msg.length>5000){toast('Shorten this note to 5,000 characters before sending it to the assistant');return}
 if(noteRequest){
  const note=state.notes.find(item=>item.id===savedNoteId);if(!note||state.notePendingIds.includes(savedNoteId))return;delete state.noteErrors[savedNoteId];
  if(!state.aiConfigured){state.noteErrors[savedNoteId]='AI chat and live search are not connected. Configure AI_BASE_URL, AI_API_KEY, and AI_MODEL on the server.';render();return}if(!accessCode('chat'))return;
  state.notePendingIds.push(savedNoteId);render();
  try{const context={selectedProduct:state.query,offers:state.results.slice(0,16).map(p=>({store:p.merchant,itemPriceSGD:p.price,title:p.title,sourceUrl:p.url,imageUrl:p.image})),liveSearchTimestamp:state.fetchedAt,isSearchData:!!state.fetchedAt,budgetEstimate:false,savedNoteRequest:true,savedNoteCategory};const reply=await requestAIReply(msg,[],context);const currentNote=state.notes.find(item=>item.id===savedNoteId);if(currentNote){currentNote.answer=reply.startsWith('Hello!')?reply:`Hello! ${reply}`;save()}}
  catch(error){state.noteErrors[savedNoteId]=error.name==='TimeoutError'?'AI response timed out. Please try again.':error.message||'Unable to answer this note. Please try again.'}
  finally{state.notePendingIds=state.notePendingIds.filter(id=>id!==savedNoteId);render()}
  return;
 }
 if(showUserMessage)addFirstUserMessage(msg);if(/\b(cheap|lowest|best price)\b/i.test(msg)&&state.results.length){addChat('assistant',cheapestText());return}if(/\b(compare|summary|results|deals?)\b/i.test(msg)&&state.results.length){addChat('assistant',summaryText());return}if(!state.aiConfigured){addChat('assistant','AI chat and live search are not connected. Configure AI_BASE_URL, AI_API_KEY, and AI_MODEL on the server.',true);return}if(!accessCode('chat'))return;
 state.chatPending=true;state.chatPendingText='Thinking…';renderRight();try{const history=state.chats.slice(-12,-1).filter(x=>!x.error).map(x=>({role:x.role,text:x.text}));const context={selectedProduct:state.query,offers:state.results.slice(0,16).map(p=>({store:p.merchant,itemPriceSGD:p.price,title:p.title,sourceUrl:p.url,imageUrl:p.image})),liveSearchTimestamp:state.fetchedAt,isSearchData:!!state.fetchedAt,budgetEstimate:false,savedNoteRequest:false,savedNoteCategory};addChat('assistant',await requestAIReply(msg,history,context))}catch(error){addChat('assistant',error.message||'Unable to answer this note. Please try again.',true)}finally{state.chatPending=false;state.chatPendingText='';renderRight()}}
document.addEventListener('submit',e=>{if(e.target.id==='top-search'){e.preventDefault();search($('top-query').value)}else if(e.target.id==='chat-form'){e.preventDefault();const value=$('chat-text').value;chat(value)}else if(e.target.id==='promo-form'){e.preventDefault();findPromoCodes($('promo-query').value)}else if(e.target.id==='note-form'){e.preventDefault();const title=$('note-title').value.trim(),text=$('note-text').value.trim(),selectedCategory=document.querySelector('input[name="note-category"]:checked')?.value||'general',category=NOTE_CATEGORIES.some(item=>item.id===selectedCategory)?selectedCategory:'general';if(!title){toast('Enter a name for your note');return}if(!text){toast('Write a note before saving');return}state.notes.push({id:`note-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,title,text,category,createdAt:new Date().toISOString()});save();toast('Note saved');render()}});
document.addEventListener('toggle',e=>{const details=e.target;if(!details.matches?.('.saved-note-answer'))return;const noteId=details.dataset.noteId;if(!noteId)return;state.expandedNoteAnswers=details.open?Array.from(new Set([...state.expandedNoteAnswers,noteId])):state.expandedNoteAnswers.filter(id=>id!==noteId)},true);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='page'){state.page=id;render();return}if(a==='cart-receipt-open'){state.cartReceiptOpen=true;renderCartReceipt();return}if(a==='cart-receipt-close'||a==='cart-receipt-backdrop'&&e.target===el){state.cartReceiptOpen=false;renderCartReceipt();return}if(a==='starter-prompt'){chat(el.dataset.prompt||'');return}if(a==='promo-save-code'){const index=Number(el.dataset.index);if(Number.isInteger(index)&&index>=0)savePromoCode(index);return}if(a==='promo-remove'){state.savedPromos=state.savedPromos.filter(promo=>promo.id!==id);save();toast('Saved promo codes removed');render();return}if(a==='save'||a==='cart-add'){const p=findResult(id);if(p)addSnapshot(a==='save'?'saved':'cart',p);return}if(a==='chat-cart-add'){const p=state.chatProducts[Number(el.dataset.index)];if(p&&!cartContains(p))addSnapshot('cart',p);return}if(a==='saved-note-cart-add'){const p=state.noteProducts[el.dataset.noteId]?.[Number(el.dataset.index)];if(p&&!cartContains(p))addSnapshot('cart',p);return}if(a==='note-products'){const note=state.notes.find(item=>item.id===id);if(!note){toast('Save the note before sending it to the assistant');return}el.closest('details')?.removeAttribute('open');chat(note.text,{savedNoteId:note.id,savedNoteCategory:note.category||'general'});return}if(a==='note-remove'){state.notes=state.notes.filter(note=>note.id!==id);state.expandedNoteAnswers=state.expandedNoteAnswers.filter(noteId=>noteId!==id);save();toast('Note deleted');render();return}if(a==='cart-remove-index'){const index=Number(el.dataset.index);if(Number.isInteger(index)&&index>=0&&index<state.cart.length){state.cart.splice(index,1);save();render()}return}if(a==='save-remove'||a==='cart-remove'){const field=a==='save-remove'?'saved':'cart';state[field]=state[field].filter(x=>x.url!==el.dataset.url);save();render();return}if(a==='help'){addChat('assistant','I can search the web for current shopping information, answer questions, and help you review sourced results. Store account access, promo-code redemption, and automatic checkout are not available.');return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.cartReceiptOpen){state.cartReceiptOpen=false;renderCartReceipt()}});
render();checkStatus();
